insert into public.bastide_scenario_items (id,title,kind,category,description,player_description,mj_notes,mechanical_base,active,sort_order,equipment) values
('bastide-mushroom-red-tison','Champignon rouge — Tison','object','Consommable','Éclater le chapeau et respirer ses spores consomme le champignon. Une chaleur intérieure protège du froid naturel et sèche progressivement les vêtements humides pendant 20 minutes. Aucune protection contre le feu, les dégâts magiques ou les dégâts déjà subis. Une dose pour une personne ; les doses ne cumulent pas la puissance.','Petit champignon rouge au chapeau charnu. Une odeur de bois chaud se dégage lorsqu’on le froisse. Ses propriétés restent à découvrir.','Création maison COF2 Bastide. Valeur indicative identifiée : 5 PA pièce. Reprise conseillée par Mila : 2 PA. Aucun tarif révélé automatiquement sur la version non identifiée. Effets inconnus par défaut à l’envoi ; le MJ choisit de les révéler. Sans effet sur les spores de vent bleues ni les tête-de-cœur de Tarak.','Création maison Bastide. Valeur unitaire : 5 PA.',true,240,'{}'::jsonb),
('bastide-mushroom-green-lanterne','Champignon vert — Lanterne','object','Consommable','Éclater le chapeau et respirer ses spores consomme le champignon. Pendant 20 minutes, la peau et les cheveux deviennent phosphorescents et éclairent à 3 mètres. Impossible de se dissimuler dans l’obscurité tant que la lueur est visible ; se couvrir masque la lumière. Une dose pour une personne ; les doses ne cumulent pas la puissance.','Petit champignon vert dont les lamelles luisent très faiblement dans le noir. Ses propriétés restent à découvrir.','Création maison COF2 Bastide. Valeur indicative identifiée : 8 PA pièce. Reprise conseillée par Mila : 4 PA. Aucun tarif révélé automatiquement sur la version non identifiée. Effets inconnus par défaut à l’envoi ; le MJ choisit de les révéler. Sans effet sur les spores de vent bleues ni les tête-de-cœur de Tarak.','Création maison Bastide. Valeur unitaire : 8 PA.',true,241,'{}'::jsonb),
('bastide-mushroom-clear-gorge','Champignon transparent — Gorge de verre','object','Consommable','Éclater le chapeau et respirer ses spores consomme le champignon. Pendant 20 minutes, aucun son ne sort de la gorge : impossible de parler, chanter ou appeler à l’aide. Respiration, gestes et écriture restent normaux. Les capacités exigeant explicitement une voix utilisable ne peuvent pas être employées ; ne pas étendre ce blocage aux autres capacités. Une dose pour une personne ; les doses ne cumulent pas la puissance.','Champignon translucide, presque vitreux, parcouru de fines nervures. Ses propriétés restent à découvrir.','Création maison COF2 Bastide. Valeur indicative identifiée : 3 PA pièce. Reprise conseillée par Mila : 1 PA. Aucun tarif révélé automatiquement sur la version non identifiée. Effets inconnus par défaut à l’envoi ; le MJ choisit de les révéler. Sans effet sur les spores de vent bleues ni les tête-de-cœur de Tarak.','Création maison Bastide. Valeur unitaire : 3 PA.',true,242,'{}'::jsonb)
